import { NextRequest, NextResponse } from "next/server"
import { readFile } from "fs/promises"
import path from "path"

export async function GET(request: NextRequest) {
    const prefersDark =
        request.headers.get("sec-ch-prefers-color-scheme") === "dark" ||
        request.headers.get("user-agent")?.toLowerCase().includes("dark");

    console.log(1, request.headers);

    const fileName = prefersDark ? "dark/manifest.json" : "light/manifest.json";
    const filePath = path.join(process.cwd(), "public", fileName);

    const data = await readFile(filePath, "utf-8")

    return new NextResponse(data, {
        headers: {
            "Content-Type": "application/manifest+json",
            "Cache-Control": "no-cache",
        },
    })
}
